styles['Heading1'].fontSize=15;styles['Heading1'].leading=20;styles['Heading1'].spaceAfter=12
styles['Heading2'].fontSize=11;styles['Heading2'].leading=15
story=[];sections=[]
def p(text,small=False):
    story.append(Paragraph(text,styles['SmallAcademic' if small else 'BodyAcademic']))
def heading(text):story.append(Paragraph(text,styles['Heading1']));sections.append(text)
def caption(text):story.append(Paragraph(text,styles['CaptionAcademic']))
def table(headers,rows,widths=None):
    data=[[Paragraph(html.escape(str(x)),styles['SmallAcademic']) for x in headers]]+[[Paragraph(html.escape(str(x)),styles['SmallAcademic']) for x in row] for row in rows]
    t=Table(data,colWidths=widths or [480/len(headers)]*len(headers),repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E8EDF1')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#BBC4CC')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),3)]))
    story.append(t);story.append(Spacer(1,10))
def figure(path,width=480):
    w,h=ImageReader(str(path)).getSize();story.append(Image(str(path),width=width,height=width*h/w))
def page():story.append(PageBreak())
def fmt(x):return f'{float(x):.6g}'
def original_means(dataset):return {r['metric']:r['mean'] for r in original['aggregate_rows'] if r['dataset']==dataset}
def common_rows(dataset):return [r for r in common if r['dataset']==dataset and r['units']==('author_units' if dataset=='fifa' else 'raw_count')]
def common_mean(dataset,method):
    rows=[r for r in common_rows(dataset) if r['method']==method]
    return {k:statistics.mean(float(r[k]) for r in rows) for k in ['MSE','RMSE','MAE','R2']}

story.append(Paragraph('Base Article Reproduction and Methodological Validation',styles['Title']))
p('Prophet and LSTM forecasting for Kubernetes autoscaling',small=True)
p('Research project: A Calibrated Uncertainty Aware Digital Twin for SLO Constrained Kubernetes Autoscaling Under Dynamic Workloads',small=True)
p('Report date: 9 October 2026',small=True)
heading('Abstract')
p('The released forecasting code of Guruge and Priyadarshana was retrained twice on each official dataset. Its scores closely approach the published hybrid rows, while source inspection confirms that the released evaluation combines next-row residual predictions with current-row targets and fits transformations using test data. Separate chronological, causal one-minute evaluations produce higher error. Local Kubernetes integration uses the unchanged author scaler and Spring Boot source on K3s; four controlled workload scenarios are executed under forecast-driven KEDA and CPU HPA. The results establish an executable baseline and identify evaluation and deployment limitations. They do not validate a new Digital Twin or uncertainty method.')
heading('Article and provenance')
p('Guruge and Priyadarshana (2025), <i>Time series forecasting-based Kubernetes autoscaling using Facebook Prophet and Long Short-Term Memory</i>, Frontiers in Computer Science, volume 7, article 1509165 [R1]. The forecasting benchmark addresses demand prediction for proactive replica allocation. The offline hybrid rows in Tables 4 and 5 are the reproduced publication targets; standalone comparator rows are not reproduced.')
table(['Official component','Audited commit'],[['Forecasting','354f0042ae7d5812dc7a44335a56b4992e853483'],['Preprocessing','0e8bc6697f2bf9c147b8fb7a6a757a5107874ee9'],['KEDA scaler','dabb205b2d03d594b45d152404229638d497380b'],['Spring Boot application','02f381511d22a5dfba29031da7f4c828620c4235']],[140,340])
p('The untouched forecasting checkout, original executed notebooks, CSVs and prior logs remain preserved. Public source licences and attribution accompany the code. Newly authored corrections, workload tools and deployment adaptations have separate directories. No remote GitHub changes were pushed.',small=True)

page();heading('System architecture and model methodology')
d=Drawing(480,180)
nodes=[(5,115,100,45,'HTTP workload','Sample API pods'),(125,115,100,45,'Prometheus','HTTP request rate'),(245,115,100,45,'Prophet plus LSTM','Point forecast'),(365,115,105,45,'Replica planning','Forecast / capacity'),(365,25,105,45,'KEDA and HPA','Kubernetes API'),(5,25,100,45,'ReplicaSet','Ready pods')]
for x,y,w,h,l1,l2 in nodes:
    d.add(Rect(x,y,w,h,fillColor=colors.HexColor('#EDF2F5'),strokeColor=colors.HexColor('#536572'),strokeWidth=.7))
    d.add(String(x+w/2,y+27,l1,textAnchor='middle',fontName='Helvetica-Bold',fontSize=8));d.add(String(x+w/2,y+12,l2,textAnchor='middle',fontSize=7.5))
for x1,y1,x2,y2 in [(105,137,125,137),(225,137,245,137),(345,137,365,137),(418,115,418,70),(365,47,105,47),(55,70,55,115)]:
    d.add(Line(x1,y1,x2,y2,strokeWidth=1));dx=x2-x1;dy=y2-y1
    if abs(dx)>abs(dy):d.add(Polygon([x2,y2,x2-5*(1 if dx>0 else -1),y2+3,x2-5*(1 if dx>0 else -1),y2-3],fillColor=colors.black))
    else:d.add(Polygon([x2,y2,x2-3,y2-5*(1 if dy>0 else -1),x2+3,y2-5*(1 if dy>0 else -1)],fillColor=colors.black))
story.append(d);caption('Figure 1. Reconstructed MAPE architecture from the article and released scaler. The local adaptation places the author scaler on the WSL host; KEDA, Prometheus and application replicas run in Kubernetes.')
p('Prophet estimates trend and seasonal structure. A two-layer LSTM predicts the remaining residual from one preceding row. The released notebooks combine these point predictions and measure held-out error. Source settings are linear Prophet growth for NASA and flat growth for WorldCup98; changepoint prior 5.1, yearly seasonality disabled, weekly Fourier order 20, daily order 50, and seasonality prior 30. The LSTM has two layers of 50 units, a single linear dense output, Adam at its default learning rate 0.001 and MSE loss. Batch size is 16, maximum epochs 20 and early stopping patience five with best-weight restoration. Neural validation uses the final 20 percent of training pairs. Hyperparameter tuning is disabled in the executed main notebooks.')
p('The article prints 50 epochs and labels seasonality twice as weekly; released code caps fitting at 20 and explicitly distinguishes weekly and daily terms. Baseline runs retain the code settings. All four faithful fits stopped after six epochs and restored epoch-one validation weights. Only NumPy and TensorFlow seeds are set by the authors, so numerical initialization is not fully controlled.')
p('The live scaler queries a one-minute Prometheus rate, multiplies by scaleFactor 100, predicts one minute ahead, divides by podLimit 1000, and returns an external metric with target one. KEDA creates an HPA; Kubernetes converts the metric to an integer replica recommendation subject to limits and stabilization [D1, D2]. The original threshold below ten substitutes the current measured value. IsActive always returns true. Forecast uncertainty and application latency are not inputs to the released scaling decision.')

page();heading('Datasets and experimental environment')
table(['Property','NASA HTTP','WorldCup98'],[[key,audit['datasets']['nasa'][k],audit['datasets']['fifa'][k]] for key,k in [('Observed minute rows','n_rows'),('Total requests','total_requests'),('First timestamp','first'),('Last timestamp','last'),('Missing calendar minutes','missing_minutes'),('Prophet training rows','prophet_train_rows'),('Original scored test rows','test_rows'),('Original neural validation pairs','lstm_validation_pairs')]],[190,145,145])
p('The author CSVs aggregate requests by observed minute and contain no duplicate timestamps or explicit zero rows. NASA uses naive local timestamps; the WorldCup reconstruction tool emits UTC timestamps stored without timezone metadata. Raw trace reconstruction was not repeated. Byte hashes and exact input filenames are recorded in reports/source-audit.json. The chronological split is 70 percent training and 30 percent test: NASA begins testing on 15 August 1995; WorldCup98 begins on 30 June 1998 at 19:30.')
p('The publication describes zero filling, but the released CSVs omit calendar gaps. Filling these gaps with zero would assert an unverified absence of traffic, particularly across documented NASA collection gaps. The corrected exercise retains observed data and excludes target/source pairs that are not exactly one minute apart. NASA therefore scores 24,390 of 24,419 original targets; WorldCup98 scores all 37,590 targets.')
table(['Environment','Executed settings'],[['Forecasting','Windows 11 x64; Python 3.12.14; TensorFlow 2.17.0 and Keras 3.4.1; Prophet 1.1.5; NumPy 1.26.4; pandas 2.2.2; scikit-learn 1.5.1'],['Host resources','Intel Core i7 1255U; 10 cores and 12 logical processors; about 15.8 GiB visible RAM; CPU only'],['Local Kubernetes','Ubuntu 24.04.1 under WSL2; K3s v1.33.6+k3s1; containerd 2.1.5; KEDA 2.18.0; Prometheus 2.55.1'],['Application','Author Spring Boot 3.4.2 source; Java 21; 250m CPU and 384Mi memory requests; 500m CPU and 512Mi limits; 256 MiB JVM heap'],['Scaler execution','Author NASA checkpoints; separate Linux Python environment; regenerated gRPC stubs; CPU intra-op 4 and inter-op 2']],[115,365])
p('Windows and Linux package freezes are separate. Linux dependencies were resolved for the live integration, not substituted into the faithful Windows experiments. Forecast calculations retain oneDNN defaults. Historical author hardware and complete dependency locks are unavailable, so exact timing or initialization differences cannot be attributed to a single cause.',small=True)

page();heading('Published and faithfully reproduced forecasts')
for ds,title in [('nasa','NASA HTTP'),('fifa','WorldCup98 in author normalized units')]:
    story.append(Paragraph(title,styles['Heading2']));mean=original_means(ds);target=audit['published_prophet_lstm'][ds]
    table(['Metric','Published','Repeat mean','Difference','Difference percent'],[[k,fmt(target[k]),fmt(mean[k]),fmt(mean[k]-target[k]),fmt(100*(mean[k]-target[k])/target[k])] for k in ['MSE','RMSE','MAE','R2','TPT_ms']],[70,95,105,105,105])
p('Differences are repeat mean minus the printed publication value. WorldCup MSE is coarsely rounded in the article, limiting percentage precision. NASA repeat RMSE ranges from 8.017708 to 8.025560; WorldCup normalized RMSE ranges from 0.003363786 to 0.003395211. Two repeats establish observed variability, not confidence intervals or statistical significance.')
p('Independent checks recomputed all four runs from saved predictions, checked dataset hashes, verified all author cell sources and confirmed successful notebook execution. Timing measures full-test Prophet prediction plus full-test LSTM prediction; it excludes training and most transformations. The reproduced timing is 37 to 38 percent higher on this CPU. It must not be interpreted as online controller latency.')
p('The first NASA attempt completed author calculations but failed in an added history exporter. Its notebook, predictions and traceback are retained and excluded from completed-run aggregates. A read-only history copy after fitting resolved the exporter failure without changing author calculations. Missing standalone comparison code and unclear five-step scoring prevent claiming reproduction of entire Tables 4 and 5.',small=True)

page();heading('Separate corrected forecasting evaluation')
p('For each eligible target minute t, the corrected forecast is Prophet(t) plus LSTM(residual(t minus 1)). Residual(t minus 1) uses only the observed preceding count and the frozen Prophet estimate at that same origin. Current target truth is never an input, and no last-row truth fallback exists. Models are fitted on the original outer 70 percent training period; test observations are available only as origins for later rolling one-step forecasts. This is an online one-step protocol with assumed immediate measurement availability, not a recursive long-horizon forecast.')
p('Scalers are fitted on the earlier neural fitting prefix, excluding neural validation and all test rows. Chronological neural validation follows that prefix. Prophet still fits the entire outer training period, so neural validation is conditional on this fitted Prophet and is not an independent full-pipeline validation set. The outer test remains untouched by fitting. Full Python, NumPy and Keras random state is set to seed 42; gap pairs are removed. Model architecture, priors, batch size and 20-epoch cap remain unchanged.')
for ds,title in [('nasa','NASA common target rows in request counts'),('fifa','WorldCup common target rows in author display units')]:
    story.append(Paragraph(title,styles['Heading2']));m1=common_mean(ds,'original_common_targets');m2=common_mean(ds,'corrected');m3=common_mean(ds,'persistence')
    table(['Metric','Original repeat mean','Corrected','Persistence'],[[k,fmt(m1[k]),fmt(m2[k]),fmt(m3[k])] for k in ['MSE','RMSE','MAE','R2']],[70,150,130,130])
p('WorldCup corrected training-scale RMSE is 0.005787535, while raw-count RMSE is 890.5685. For direct display comparison only, both forecasts above are expressed using the same fixed author full-series scale; this post-evaluation conversion does not change model inputs or fit a test-dependent training transform. Persistence RMSE is 762.7463 requests, lower than the corrected hybrid on this single run. NASA corrected RMSE is 14.2902 requests, lower than persistence at 16.3871.')
p('The error increase follows a joint change of target alignment, scaling, gap eligibility and complete seeding. This exercise does not isolate the contribution of each change. Scores now quantify a genuinely future target rather than the released mixture of current and next residuals. One corrected fit per dataset was executed; stochastic or per-change conclusions require further separately labelled experiments.',small=True)

page();heading('Forecast comparison figures')
figure(OUT/'figures/nasa-comparison.png');caption('Figure 2. NASA full test set on common consecutive-minute targets. The faithful output is shown with its retained author scoring alignment; the corrected output forecasts the target from its preceding observation.')
figure(OUT/'figures/fifa-comparison.png');caption('Figure 3. WorldCup98 in raw requests per minute. Corrected and faithful outputs use the same target rows and physical units. Large request spikes dominate squared error, so a high overall R squared does not establish predictive reliability at a burst.')
p('Saved predictions contain origin timestamps, target timestamps, source and target row numbers, origin residuals and raw-count forecasts. Independent checks verify one-minute origin gaps, training-prefix scaler extrema, model reload inference, score recomputation and unchanged origin inputs when future observations are perturbed. No calibration coverage, Digital Twin fidelity or latency-SLO inference is claimed from these forecasting plots.',small=True)

page();heading('Kubernetes implementation and execution evidence')
p('Docker Desktop initially failed during initialization of inaccessible Windows inference and secrets sockets. Recoverable backups of transient directories did not cure recurrent failures. Existing container data was not reset. Both experiment sequences were therefore executed on a separate K3s server in Ubuntu WSL [D3], without enabling automatic boot startup. Docker later became available after Windows restart and sign-in; successful Docker API checks do not change the recorded K3s experiment environment.')
p('The image named in the author deployment manifest returned authorization or missing-repository errors. The application README names a different image, spring-boot-api-with-prometheus, whose registry manifest later proved accessible; that alternative was not deployed. The unchanged Java source was built with Maven. Its original context test initially failed because Mockito could not dynamically attach under WSL; an explicit premain agent made the original test pass. The author JAR runs read-only in a Temurin container via a node-specific hostPath mount.')
p('The unchanged author scaler runs on the WSL host using its released NASA model files. Its protobuf stubs are regenerated with grpcio-tools 1.62.3 and protobuf 4.25.8 to meet TensorFlow 2.17 compatibility. Kubernetes routes its external gRPC Service to the WSL node address. This retains the author forecasting and metric calculation, but the scaler is not containerized; its memory and CPU are excluded from application pod-minutes. Sixteen local real-gRPC model calls with mocked Prometheus passed separately; that test is labelled as interface evidence, not cluster performance.')
p('The live run uses Prometheus pod discovery at five-second scrape intervals, the author one-minute request-rate query, scaleFactor 100, podLimit 1000, activation threshold ten, polling 60 seconds and replica limits one to ten. Application resources are explicit so CPU HPA can target 70 percent of the CPU request. Forecast-driven KEDA and CPU HPA own the deployment at different times. No two HPA controllers act concurrently.')
p('The sixteen Windows interface calls took 80.645 to 314.906 ms, with median 102.427 ms, including local gRPC and real model inference against mocked Prometheus. These are not Linux live-controller timings. Live scaler CPU and memory, complete control-loop overhead and distribution-shift robustness were not independently sampled; they remain measurement limits.',small=True)
table(['Scenario','Offered requests per second in four phases'],[['Stable','5, 5, 5, 5'],['Increasing','2, 10, 20, 40'],['Spike','5, 5, 50, 5'],['Decreasing','40, 20, 10, 2']],[110,370])
p('Each measured phase lasts 30 seconds; four scenarios run consecutively per controller after a discarded 60-second warm-up. Requests follow an open-loop schedule with up to 200 HTTP connections and a ten-second request timeout. The local SLO is at least 99 percent HTTP success within 500 ms over a scenario, counting failures as violations. Replica and metrics-server snapshots retain actual elapsed timestamps. Short phases and inherited state limit stabilization and capacity conclusions. The article identifies direct integration and KEDA as further work; this is an authored integration experiment using released author code, not a replay of a published cluster benchmark.')
p('Final comparisons use scheduling-validated run-03. Earlier run-01 is preserved but excluded: its initial forecast phase lasted 198 seconds instead of 30, the first successful monitor sample was at 206 seconds, and warm-up was unmatched. Its initial forecast stable scenario had P95 860.160 ms and 11.833 percent SLO violations; these diagnostic observations cannot establish controller inferiority. Run-02 stopped before traffic due a 40-second wrapper timeout around a 180-second rollout wait. The retry extends that wrapper and keeps the WSL session active.',small=True)

page();heading('Measured autoscaling outcomes')
records=sorted(cluster['scenarios'],key=lambda r:(r['controller'],['stable','increasing','spike','decreasing'].index(r['scenario'])))
table(['Controller and scenario','Requests','P95 ms','P99 ms','Failed','SLO bad percent','Pod min','CPU percent'],[[r['controller']+' '+r['scenario'],r['requests'],fmt(r['p95_ms']),fmt(r['p99_ms']),r['failed'],fmt(r['slo_violation_fraction']*100),fmt(r['sampled_pod_minutes']),fmt(r['mean_cpu_utilization_percent_of_request'])] for r in records],[110,55,45,45,35,70,60,60])
p('CPU utilization is relative to the 250m request per application pod and comes from metrics-server sliding-window measurements. Application pod-minutes integrate sampled desired replicas; memory and raw pod measurements are in the results. Pod-minutes describe local resource allocation, not monetary cost. P95 and P99 use recorded end-to-end HTTP timings, including failed or timed-out requests. A request-level violation fraction above one percent fails the experiment SLO.')
figure(ROOT/f'kubernetes-autoscaling/results/forecast/{selected_run}/cluster-plot.png');caption('Figure 4. Forecast-driven KEDA sequence. The desired and ready replica counts are actual API observations. Vertical boundaries separate scenarios; grey traffic shows the offered schedule, not achieved throughput.')

page();heading('Autoscaling comparison and practical limits')
figure(ROOT/f'kubernetes-autoscaling/results/hpa/{selected_run}/cluster-plot.png');caption('Figure 5. CPU HPA sequence on the same application and offered traffic. One sequence per controller and short phases do not support statistical superiority claims.')
forecast=[r for r in records if r['controller']=='forecast'];hpa=[r for r in records if r['controller']=='hpa']
fp=sum(r['sampled_pod_minutes'] for r in forecast);hp=sum(r['sampled_pod_minutes'] for r in hpa)
p(f'Total sampled application allocation is {fp:.3f} pod-minutes for the forecast controller and {hp:.3f} for CPU HPA. Per-scenario replica ranges and observed time to first replica change are saved in each summary. A null response time is right-censored within the phase, not a zero-latency decision. HPA scale-down stabilization can exceed the entire short phase; no unobserved scale-down is reported as successful.')
p('Sequential execution, inherited application state and one sequence per controller remain confounders after warm-up. HPA first-change delays are 12.158 and 14.606 seconds in spike phases zero and three, respectively; these are sampled changes, not causal attribution to a single traffic step. First desired-to-ready observations imply lags of about 59 seconds for two replicas and 70 seconds for three. Sampling and collection overhead prevent interpreting these as exact startup durations.')
p('The scheduling-validated sequences each contain 6,870 requests, with zero failed requests and zero violations of the 500 ms threshold. The forecast controller holds three desired and ready replicas during measured traffic. HPA begins with one replica, increases to three during the spike scenario, and retains three during decreasing traffic. The short decreasing scenario cannot establish completion of the default five-minute downscale stabilization window. All per-phase first-change delays and their censoring flags are retained in the result summaries.')
p('These workloads exercise control plumbing and a cheap success-response endpoint. They do not reproduce an overloaded multi-service application or establish universal capacity at podLimit 1000. ScaleFactor 100 is an author parameter, not a measured requests-per-second to requests-per-minute calibration. Queueing, heterogeneous request cost and delayed readiness are not explicitly modeled by the released decision rule.')
p('The scaler applies historical NASA checkpoints to a current wall-clock date. Its residual uses current observed traffic minus a future Prophet value rather than the Prophet value at the current origin. This differs from the causal residual construction validated above and introduces a time and workload transfer concern. These behaviors are preserved in the live reproduction. Any resource inefficiency observed here is conditional on these checkpoints, the trivial application and local settings; broad SLO or drift claims remain hypotheses.')

page();heading('Research gap supported by evidence')
p('<b>Confirmed baseline limitations.</b> Source and executed validation establish misaligned scoring, test-dependent scaling, a truth fallback, missing calendar rows and paper/code configuration differences. Corrected WorldCup persistence outperforms the hybrid in this one-step run. The live rule consumes point estimates, ignores calibration and latency, uses historical checkpoints at a new date, and relies on a fixed capacity ratio. No formal end-to-end SLO guarantee follows from a low offline error or from functioning KEDA actuation.')
p('<b>Existing uncertainty work.</b> AAPA uses beta-calibrated workload-classifier confidence and archetype-dependent scaling; its reported evaluation uses a SimPy simulator [R3]. It is relevant prior art for uncertainty-aware control, although classifier confidence is different from coverage-calibrated workload intervals. BACC combines adaptive conformal inference and budget-paced PI control with both simulation and Kubernetes replay [R5]. Its end-to-end implementation targets CPU-threshold crossings, so adding conformal calibration or error-budget control alone is already occupied research territory.')
p('<b>Existing Digital Twin work.</b> KubeTwin describes a Kubernetes Digital Twin framework with MEC deployment validation [R2]; this assessment is limited to the institutional abstract, with the publisher manuscript restricted and the institutional page inaccessible during the final recheck. KARMA builds a trace-based Twin, trains agents in simulation and transfers policies to Kubernetes [R4]. Adding a Kubernetes Twin alone is therefore not new. Chen et al. combine quantile uncertainty and robust MPC in a manufacturing Twin [R7]. ADAPT already adjusts proactive horizons using online cold-start estimates in simulation [R6].')
p('<b>Defensible candidate gap.</b> Investigate whether separately calibrated workload uncertainty and uncertainty in a validated workload-to-tail-latency Twin can jointly improve a request-level latency SLO and resource tradeoff under abrupt shifts, measurement delay and variable readiness. The research must establish whether Twin fidelity errors invalidate forecast-only coverage, whether recalibration restores decision reliability, and when the added prediction and controller overhead exceeds the benefit. This is a testable question, not a proven novelty or effectiveness claim.')
p('<b>Evidence still required.</b> Bursty and shifted workloads with real contention; repeated cluster runs; Twin prediction-error and interval-coverage diagnostics; explicit latency budgets; readiness and observation-delay sensitivity; fair HPA, corrected point-forecast, AAPA-like, BACC-like and Twin-only comparisons. These belong to the subsequent contribution phase and were not implemented here. The targeted literature review is current to 9 October 2026 but is not a systematic proof that no equivalent integration exists. A repository entry dated November 2026 was excluded pending date verification.')

page();heading('Reproducibility status and conclusion')
table(['Deliverable','Status'],[['Faithful forecasting','Four executed and independently checked runs; original evidence preserved'],['Corrected forecasting','Two executed fits; causal-input and saved-model checks passed; common-unit comparisons exported'],['Kubernetes integration','K3s, KEDA, Prometheus and author application deployed; both controller sequences executed'],['Research contribution','Uncertainty calibration, Digital Twin and new SLO decision policy not implemented'],['Remaining limits','No comparator table replication, no statistical cluster repeats, no long scale-down test, no real workload-shift or overload campaign']],[150,330])
p('The reproduction establishes the released model behavior and working local actuation, while the corrected evaluation changes the interpretation of forecast accuracy. It supports using a separately labelled causal point-forecast baseline in later research. It does not establish that a calibrated Digital Twin will improve SLO compliance or resource use; that conclusion requires the planned independent experiments and comparison with existing approaches.')
p('The comprehensive README gives exact executed commands and portable path substitutions. Source licences, hashes, package freezes, build failures and adaptations are retained. Independent QA verifies paper numbers against extracted source tables, original metrics against saved CSVs, corrected model inference, original evidence preservation, application source identity and eight live controller/scenario result records. Archive deduplication preserves duplicate path mappings instead of deleting existing files.',small=True)
